import SwiftUI

// UI helpers for the core's types. The types themselves (`Mode`, `Tier`, `Category`, `Overview` and so
// on) are generated by UniFFI from `core/crates/ffi` into `Generated/roomy_core.swift`, as described in
// `docs/command-contract.md` (T09). Nothing here changes what the core says; it only words and draws it.

extension Mode {
    /// Every mode, in picker order. (UniFFI enums are not `CaseIterable`.)
    static let allCases: [Mode] = [.simple, .developer]

    /// Short name, used in the picker and the toolbar.
    var label: String {
        switch self {
        case .simple: return "Simple"
        case .developer: return "Developer"
        }
    }

    /// One plain sentence on what the mode changes, shown in Settings.
    var explanation: String {
        switch self {
        case .simple:
            return "Shows everyday items in plain words."
        case .developer:
            return "Adds a Developer section for Xcode, Android, JavaScript and Docker, with more detail on each item."
        }
    }

    /// The value saved in settings. Kept separate from the Swift case names so renames don't lose it.
    var storageKey: String {
        switch self {
        case .simple: return "simple"
        case .developer: return "developer"
        }
    }

    init?(storageKey: String) {
        guard let mode = Mode.allCases.first(where: { $0.storageKey == storageKey }) else { return nil }
        self = mode
    }
}

extension Tier {
    static let allCases: [Tier] = [.likelySafe, .reviewFirst, .keep]

    /// The tier in words. Always shown as text, never as colour alone.
    var label: String {
        switch self {
        case .likelySafe: return "Likely safe"
        case .reviewFirst: return "Review first"
        case .keep: return "Keep"
        }
    }

    /// SF Symbol paired with the tier's text.
    var symbol: String {
        switch self {
        case .likelySafe: return "checkmark.circle.fill"
        case .reviewFirst: return "eye.circle.fill"
        case .keep: return "lock.circle.fill"
        }
    }

    /// Supporting colour. Never the only signal; no red, which is kept for real errors.
    var tint: Color {
        switch self {
        case .likelySafe: return .green
        case .reviewFirst: return .orange
        case .keep: return .gray
        }
    }
}

extension Category {
    /// Plain name for the strip legend. `SidebarItem.itemFilter` groups categories for the sidebar.
    var title: String {
        switch self {
        case .cache: return "Caches"
        case .build: return "Build files"
        case .developerTools: return "Developer tools"
        case .docker: return "Docker"
        case .appData: return "App data"
        case .logs: return "Logs"
        case .downloads: return "Downloads and installers"
        case .userData: return "Your files"
        case .backups: return "Backups"
        case .system: return "System Data"
        case .unknown: return "Not sorted"
        }
    }

    /// SF Symbol for rows in this category. All exist on macOS 13.
    var symbol: String {
        switch self {
        case .cache: return "square.grid.2x2"
        case .build: return "hammer"
        case .developerTools: return "wrench.and.screwdriver"
        case .docker: return "shippingbox"
        case .appData: return "app"
        case .logs: return "doc.text"
        case .downloads: return "arrow.down.circle"
        case .userData: return "person.crop.square"
        case .backups: return "externaldrive"
        case .system: return "gearshape"
        case .unknown: return "questionmark.folder"
        }
    }

    /// Strip colour. The legend always names the category, so colour is never the only signal.
    var color: Color {
        switch self {
        case .cache: return .blue
        case .build: return .indigo
        case .developerTools: return .purple
        case .docker: return .cyan
        case .appData: return .teal
        case .logs: return .mint
        case .downloads: return .yellow
        case .userData: return .orange
        case .backups: return .pink
        case .system: return .gray
        case .unknown: return .brown
        }
    }
}

extension Sort {
    static let allCases: [Sort] = [.largestFirst, .smallestFirst, .title]

    var label: String {
        switch self {
        case .largestFirst: return "Largest first"
        case .smallestFirst: return "Smallest first"
        case .title: return "Name"
        }
    }
}

extension Confidence {
    var label: String {
        switch self {
        case .high: return "High"
        case .medium: return "Medium"
        case .low: return "Low"
        }
    }
}

extension Caution {
    /// Why the core was more careful with an item, in one plain sentence. Never names a place.
    var explanation: String {
        switch self {
        case .protected: return "It is, or holds, something Roomy always keeps."
        case .reviewOnly: return "It holds something you should look at first."
        case .nestedRule: return "Something else Roomy recognises is inside it."
        case .rulesDisagree: return "Roomy isn't sure what part of it is."
        case .lowConfidence: return "Roomy isn't sure what it is."
        case .unreadable: return "Part of it couldn't be read."
        case .unusualName: return "A name inside it couldn't be checked."
        }
    }
}

extension ItemSummary: Identifiable {}

extension CategoryTotal: Identifiable {
    public var id: Category { category }
}

extension ScanPhase {
    /// True once the scan has stopped, for any reason.
    var hasEnded: Bool {
        switch self {
        case .scanning, .classifying: return false
        case .finished, .cancelled, .failed: return true
        }
    }
}
